// Aggregate check-ins by department and build a summary object.
const rows = $input.all().map(i => i.json);

const today = new Date().toLocaleDateString('en-IN', {
  day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Asia/Kolkata'
});

const deptMap = {};
for (const row of rows) {
  const dept = row.department || 'Unassigned';
  if (!deptMap[dept]) deptMap[dept] = { present: 0, absent: 0, late: 0, employees: [] };

  const status = row.status || 'present';
  if (status === 'absent') deptMap[dept].absent++;
  else if (status === 'late') { deptMap[dept].late++; deptMap[dept].present++; }
  else deptMap[dept].present++;

  deptMap[dept].employees.push({
    name:         row.employee_name,
    status,
    hours_worked: row.hours_worked ?? 0,
    check_in:     row.check_in_time
      ? new Date(row.check_in_time).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' })
      : '—',
    check_out:    row.check_out_time
      ? new Date(row.check_out_time).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' })
      : 'Not checked out',
  });
}

const totalPresent = rows.filter(r => r.status !== 'absent').length;
const totalAbsent  = rows.filter(r => r.status === 'absent').length;
const totalLate    = rows.filter(r => r.status === 'late').length;

// Build a human-readable WhatsApp message (plain text, 1024 char limit per section)
let message = `📋 *Attendance Report — ${today}*\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━\n`;
message += `✅ Present : ${totalPresent}\n`;
message += `❌ Absent  : ${totalAbsent}\n`;
message += `⏰ Late    : ${totalLate}\n\n`;

for (const [dept, data] of Object.entries(deptMap)) {
  message += `*${dept}* (P:${data.present} A:${data.absent} L:${data.late})\n`;
  for (const emp of data.employees) {
    const icon = emp.status === 'absent' ? '❌' : emp.status === 'late' ? '⏰' : '✅';
    message += `  ${icon} ${emp.name} — In: ${emp.check_in} | Out: ${emp.check_out} | ${emp.hours_worked}h\n`;
  }
  message += '\n';
}

return [{
  json: {
    date: today,
    total_present: totalPresent,
    total_absent:  totalAbsent,
    total_late:    totalLate,
    departments:   deptMap,
    whatsapp_message: message.trim(),
    raw_rows: rows,
  }
}];

// Merge the report (from previous step via $('Aggregate & Build Report'))
// with each manager phone to send individual WhatsApp messages.
const report = $('Aggregate & Build Report').first().json;
const managers = $input.all().map(i => i.json);

return managers.map(mgr => ({
  json: {
    ...report,
    recipient_phone: mgr.manager_phone.replace(/[^0-9]/g, ''),
  }
}));
